bash -c "echo 'class Context(object):
    def __init__(self, cmd, cleanup_timeout=None):
        self.cmd = cmd
        self.cleanup_timeout = cleanup_timeout
        self._cleanup_timeout_set = bool(cleanup_timeout)

    def close(self):
        if self._cleanup_timeout_set:
            import signal
            import time
            try:
                signal.alarm(int(self.cleanup_timeout))
                self._cleanup()
            except Exception as e:
                print(f'Cleanup timed out: {e}')
                signal.alarm(0)
        else:
            self._cleanup()

    def _cleanup(self):
        pass' >> src/click/core.py"
